/*
 * СГЕНЕРИРОВАННЫЙ ФАЙЛ. Не править руками.
 * Источник: файлы migrations/*.sql
 * Пересборка: node scripts/build-migration-map.js
 *
 * Текст миграций для раздела «Миграции». В Cloudflare Functions нет файловой
 * системы, поэтому SQL попадает на сервер только так. Отдаётся по одной штуке
 * и только под паролем админки.
 */

export const MIGRATION_SQL: Readonly<Record<string, string>> = {
  '0001_create_articles.sql': "-- D1 migration: primary table for blog articles\nCREATE TABLE IF NOT EXISTS articles (\n  id INTEGER NOT NULL,\n  slug TEXT NOT NULL,\n  title TEXT NOT NULL,\n  category TEXT NOT NULL DEFAULT 'Блог',\n  read_time TEXT NOT NULL DEFAULT '',\n  date TEXT NOT NULL,\n  description TEXT NOT NULL,\n  content TEXT NOT NULL,\n  image TEXT NOT NULL DEFAULT '/og-image.jpg',\n  seo_title TEXT,\n  seo_description TEXT,\n  published_at TEXT,\n  updated_at TEXT,\n  tags_json TEXT NOT NULL DEFAULT '[]',\n  summary TEXT,\n  key_takeaways_json TEXT NOT NULL DEFAULT '[]',\n  faq_json TEXT NOT NULL DEFAULT '[]',\n  created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),\n  PRIMARY KEY (slug)\n);\n\nCREATE INDEX IF NOT EXISTS idx_articles_updated_at ON articles(updated_at);\nCREATE INDEX IF NOT EXISTS idx_articles_date ON articles(date);",
  '0002_meta_capi_diagnostics.sql': "CREATE TABLE IF NOT EXISTS meta_capi_diagnostics (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  event_name TEXT NOT NULL,\n  event_id TEXT,\n  event_time INTEGER,\n  status TEXT NOT NULL,\n  events_received INTEGER,\n  fbtrace_id TEXT,\n  error_code TEXT,\n  error_message TEXT,\n  page_path TEXT,\n  page_url TEXT,\n  service TEXT,\n  has_fbp INTEGER,\n  has_fbc INTEGER,\n  has_external_id INTEGER,\n  has_email INTEGER,\n  has_phone INTEGER,\n  has_fbclid INTEGER,\n  has_utm INTEGER,\n  marketing_consent INTEGER,\n  consent_version INTEGER,\n  consent_source TEXT,\n  consent_region TEXT,\n  consent_timestamp INTEGER,\n  created_at TEXT NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_meta_capi_diagnostics_created_at ON meta_capi_diagnostics(created_at);\nCREATE INDEX IF NOT EXISTS idx_meta_capi_diagnostics_event ON meta_capi_diagnostics(event_name, event_id);\nCREATE INDEX IF NOT EXISTS idx_meta_capi_diagnostics_status ON meta_capi_diagnostics(status, created_at);",
  '0003_meta_capi_diagnostics_quality.sql': "ALTER TABLE meta_capi_diagnostics ADD COLUMN form_id TEXT;\nALTER TABLE meta_capi_diagnostics ADD COLUMN form_variant TEXT;\nALTER TABLE meta_capi_diagnostics ADD COLUMN contact_method TEXT;\nALTER TABLE meta_capi_diagnostics ADD COLUMN lead_source_page TEXT;\nALTER TABLE meta_capi_diagnostics ADD COLUMN match_quality_score INTEGER;\n\nCREATE INDEX IF NOT EXISTS idx_meta_capi_diagnostics_form_created ON meta_capi_diagnostics(form_id, created_at);\nCREATE INDEX IF NOT EXISTS idx_meta_capi_diagnostics_page_created ON meta_capi_diagnostics(page_path, created_at);\nCREATE INDEX IF NOT EXISTS idx_meta_capi_diagnostics_quality ON meta_capi_diagnostics(match_quality_score, created_at);",
  '0004_meta_capi_diagnostics_enrichment.sql': "ALTER TABLE meta_capi_diagnostics ADD COLUMN event_source_url TEXT;\nALTER TABLE meta_capi_diagnostics ADD COLUMN page_path_normalized TEXT;\nALTER TABLE meta_capi_diagnostics ADD COLUMN lead_value REAL;\nALTER TABLE meta_capi_diagnostics ADD COLUMN lead_currency TEXT;\nALTER TABLE meta_capi_diagnostics ADD COLUMN score_identity INTEGER;\nALTER TABLE meta_capi_diagnostics ADD COLUMN score_attribution INTEGER;\nALTER TABLE meta_capi_diagnostics ADD COLUMN score_consent INTEGER;\nALTER TABLE meta_capi_diagnostics ADD COLUMN score_context INTEGER;\n\nCREATE INDEX IF NOT EXISTS idx_meta_capi_diag_norm_path_created ON meta_capi_diagnostics(page_path_normalized, created_at);\nCREATE INDEX IF NOT EXISTS idx_meta_capi_diag_value_created ON meta_capi_diagnostics(lead_value, created_at);\nCREATE INDEX IF NOT EXISTS idx_meta_capi_diag_event_source_created ON meta_capi_diagnostics(event_source_url, created_at);",
  '0005_meta_outbox.sql': "CREATE TABLE IF NOT EXISTS meta_outbox (\n  id TEXT PRIMARY KEY,\n  event_name TEXT NOT NULL,\n  event_id TEXT NOT NULL,\n  payload_json TEXT NOT NULL,\n  status TEXT NOT NULL DEFAULT 'pending',\n  attempts INTEGER NOT NULL DEFAULT 0,\n  next_retry_at INTEGER NOT NULL DEFAULT (strftime('%s','now')),\n  last_error TEXT,\n  created_at INTEGER NOT NULL DEFAULT (strftime('%s','now')),\n  updated_at INTEGER NOT NULL DEFAULT (strftime('%s','now')),\n  sent_at INTEGER\n);\nCREATE INDEX IF NOT EXISTS idx_meta_outbox_status_next_retry ON meta_outbox(status, next_retry_at);\nCREATE INDEX IF NOT EXISTS idx_meta_outbox_event ON meta_outbox(event_name, event_id);",
  '0006_articles_status_and_versions.sql': "-- Preserve draft/published state for D1-backed articles and enable private article version history.\nALTER TABLE articles ADD COLUMN status TEXT NOT NULL DEFAULT 'published';\n\nCREATE INDEX IF NOT EXISTS idx_articles_status_published_at ON articles(status, published_at);\n\nCREATE TABLE IF NOT EXISTS article_versions (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  slug TEXT NOT NULL,\n  version_data TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP)\n);\n\nCREATE INDEX IF NOT EXISTS idx_article_versions_slug_created_at ON article_versions(slug, created_at DESC);",
  '0007_articles_case_data.sql': "-- Структурированные поля кейса (ниша, источники, метрики, график)\n-- для карточек на странице /cases. Заполняются через админку.\nALTER TABLE articles ADD COLUMN case_data_json TEXT;",
  '0008_leads_and_page_stats.sql': "-- Заявки с форм сайта: копия того, что уходит в Telegram,\n-- плюс статус обработки для раздела «Заявки» в админке.\nCREATE TABLE IF NOT EXISTS leads (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  event_id TEXT UNIQUE,\n  name TEXT NOT NULL DEFAULT '',\n  email TEXT NOT NULL DEFAULT '',\n  phone TEXT NOT NULL DEFAULT '',\n  telegram_username TEXT NOT NULL DEFAULT '',\n  contact_method TEXT NOT NULL DEFAULT 'telegram',\n  budget TEXT NOT NULL DEFAULT '',\n  message TEXT NOT NULL DEFAULT '',\n  service TEXT NOT NULL DEFAULT '',\n  page_path TEXT NOT NULL DEFAULT '',\n  status TEXT NOT NULL DEFAULT 'new', -- new | in_progress | closed\n  telegram_delivered INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_leads_status_created ON leads(status, created_at);\nCREATE INDEX IF NOT EXISTS idx_leads_created ON leads(created_at);\n\n-- Дневные счётчики просмотров по страницам (без личных данных).\nCREATE TABLE IF NOT EXISTS page_stats_daily (\n  day TEXT NOT NULL,        -- YYYY-MM-DD (UTC)\n  page_path TEXT NOT NULL,\n  views INTEGER NOT NULL DEFAULT 0,\n  PRIMARY KEY (day, page_path)\n);\n\n-- Уникальные посетители за день: хранится только обезличенный хеш\n-- (IP + браузер + дата + соль), восстановить человека по нему нельзя.\n-- Хеши старше 90 дней удаляются автоматически при записи статистики.\nCREATE TABLE IF NOT EXISTS visitor_hashes_daily (\n  day TEXT NOT NULL,\n  visitor_hash TEXT NOT NULL,\n  PRIMARY KEY (day, visitor_hash)\n);\n\nCREATE INDEX IF NOT EXISTS idx_visitor_hashes_day ON visitor_hashes_daily(day);",
  '0009_leads_dedupe_quality.sql': "-- Повторные заявки и качество лида.\n-- ВНИМАНИЕ: повторный запуск даст ошибку \"duplicate column name\" — это\n-- нормально, значит колонки уже добавлены.\nALTER TABLE leads ADD COLUMN submissions_count INTEGER NOT NULL DEFAULT 1;\nALTER TABLE leads ADD COLUMN last_submitted_at TEXT;\nALTER TABLE leads ADD COLUMN quality TEXT NOT NULL DEFAULT ''; -- '' | target | nontarget\nUPDATE leads SET last_submitted_at = created_at WHERE last_submitted_at IS NULL;",
  '0010_leads_meta_quality.sql': "-- Контекст для событий качества лида в Meta CAPI (QualifiedLead / UnqualifiedLead):\n-- клик-метки и согласие сохраняются при создании заявки, чтобы позже\n-- привязать событие качества к тому же человеку и клику по рекламе.\n-- ВНИМАНИЕ: повторный запуск даст ошибку \"duplicate column name\" — это нормально.\nALTER TABLE leads ADD COLUMN fbp TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN fbc TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN event_source_url TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN external_id TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN marketing_consent INTEGER NOT NULL DEFAULT 0;",
  '0011_leads_utm.sql': "-- UTM-метки заявки: откуда пришёл лид (сохраняются вместе с заявкой,\n-- показываются в админке и в Telegram-уведомлении).\n-- ВНИМАНИЕ: повторный запуск даст ошибку \"duplicate column name\" — это нормально.\nALTER TABLE leads ADD COLUMN utm_source TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN utm_medium TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN utm_campaign TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN utm_content TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN utm_term TEXT NOT NULL DEFAULT '';",
  '0012_admin_control_center.sql': "-- Mini-CRM fields for the admin control center.\n-- Apply this migration after 0011_leads_utm.sql.\n-- Like the other ALTER TABLE migrations in this project, re-running the ALTER\n-- statements after a successful apply will report \"duplicate column name\".\n\nALTER TABLE leads ADD COLUMN pipeline_stage TEXT NOT NULL DEFAULT 'new'\n  CHECK (pipeline_stage IN ('new', 'contacted', 'discovery', 'proposal', 'won', 'lost', 'archived'));\nALTER TABLE leads ADD COLUMN next_action_at TEXT;\nALTER TABLE leads ADD COLUMN loss_reason TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN notes TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN deal_value REAL\n  CHECK (deal_value IS NULL OR (deal_value >= 0 AND deal_value <= 1000000000000));\nALTER TABLE leads ADD COLUMN deal_currency TEXT NOT NULL DEFAULT 'USD'\n  CHECK (length(deal_currency) = 3 AND deal_currency = upper(deal_currency) AND deal_currency NOT GLOB '*[^A-Z]*');\n\n-- Legacy `closed` не сообщает, была ли сделка выиграна или проиграна.\n-- Сохраняем его как нейтральный терминальный архив, не выдумывая исход сделки.\nUPDATE leads\nSET pipeline_stage = CASE status\n  WHEN 'in_progress' THEN 'contacted'\n  WHEN 'closed' THEN 'archived'\n  ELSE 'new'\nEND;\n\nCREATE INDEX IF NOT EXISTS idx_leads_pipeline_stage_next_action\n  ON leads(pipeline_stage, next_action_at);\nCREATE INDEX IF NOT EXISTS idx_leads_next_action\n  ON leads(next_action_at);\n\nCREATE TABLE IF NOT EXISTS lead_activity (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  lead_id INTEGER NOT NULL,\n  type TEXT NOT NULL,\n  \"from\" TEXT,\n  \"to\" TEXT,\n  note TEXT NOT NULL DEFAULT '',\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  FOREIGN KEY (lead_id) REFERENCES leads(id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_lead_activity_lead_created\n  ON lead_activity(lead_id, created_at DESC, id DESC);",
  '0013_site_sections.sql': "-- Типизированные текстовые секции публичных страниц.\n-- В базе хранятся только plain-text поля; HTML/CSS/JS не принимаются API.\nCREATE TABLE IF NOT EXISTS site_sections (\n  section_key TEXT PRIMARY KEY,\n  page_path TEXT NOT NULL,\n  label TEXT NOT NULL,\n  draft_json TEXT NOT NULL DEFAULT '{}',\n  published_json TEXT NOT NULL DEFAULT '{}',\n  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),\n  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),\n  published_version INTEGER CHECK (published_version IS NULL OR published_version >= 1),\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now')),\n  published_at TEXT\n);\n\nCREATE TABLE IF NOT EXISTS site_section_versions (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  section_key TEXT NOT NULL,\n  snapshot_json TEXT NOT NULL,\n  source TEXT NOT NULL DEFAULT 'draft' CHECK (source IN ('draft', 'published')),\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  FOREIGN KEY (section_key) REFERENCES site_sections(section_key) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_site_sections_status_updated\n  ON site_sections(status, updated_at DESC);\nCREATE INDEX IF NOT EXISTS idx_site_section_versions_key_created\n  ON site_section_versions(section_key, created_at DESC);",
  '0014_crm_workspace.sql': "-- Full single-owner CRM workspace for leads.\n-- Apply after 0012_admin_control_center.sql (0013 is site content and independent).\n-- ALTER TABLE statements are intentionally one-time, like the earlier lead migrations.\n\nALTER TABLE leads ADD COLUMN priority TEXT NOT NULL DEFAULT 'normal'\n  CHECK (priority IN ('low', 'normal', 'high', 'urgent'));\nALTER TABLE leads ADD COLUMN lead_score INTEGER NOT NULL DEFAULT 0\n  CHECK (lead_score BETWEEN 0 AND 100);\nALTER TABLE leads ADD COLUMN next_action_text TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN pipeline_changed_at TEXT;\nALTER TABLE leads ADD COLUMN last_contacted_at TEXT;\nALTER TABLE leads ADD COLUMN closed_at TEXT;\nALTER TABLE leads ADD COLUMN crm_revision INTEGER NOT NULL DEFAULT 0;\n\nUPDATE leads\nSET pipeline_changed_at = COALESCE(pipeline_changed_at, updated_at, created_at);\n\nCREATE INDEX IF NOT EXISTS idx_leads_crm_priority_score\n  ON leads(priority, lead_score DESC);\nCREATE INDEX IF NOT EXISTS idx_leads_crm_pipeline_updated\n  ON leads(pipeline_stage, updated_at DESC);\n\n-- Extend the existing immutable-style timeline so every CRM mutation has context.\nALTER TABLE lead_activity ADD COLUMN actor TEXT NOT NULL DEFAULT 'admin';\nALTER TABLE lead_activity ADD COLUMN entity_type TEXT NOT NULL DEFAULT 'lead';\nALTER TABLE lead_activity ADD COLUMN entity_id INTEGER;\nALTER TABLE lead_activity ADD COLUMN action_id TEXT NOT NULL DEFAULT '';\nALTER TABLE lead_activity ADD COLUMN metadata_json TEXT NOT NULL DEFAULT '{}';\n\nCREATE INDEX IF NOT EXISTS idx_lead_activity_action\n  ON lead_activity(action_id);\nCREATE INDEX IF NOT EXISTS idx_lead_activity_entity\n  ON lead_activity(lead_id, entity_type, entity_id, created_at DESC);\n\nCREATE TABLE IF NOT EXISTS crm_notes (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  lead_id INTEGER NOT NULL,\n  body TEXT NOT NULL,\n  pinned INTEGER NOT NULL DEFAULT 0 CHECK (pinned IN (0, 1)),\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now')),\n  FOREIGN KEY (lead_id) REFERENCES leads(id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_crm_notes_lead_pinned_created\n  ON crm_notes(lead_id, pinned DESC, created_at DESC, id DESC);\n\nCREATE TABLE IF NOT EXISTS crm_tasks (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  lead_id INTEGER NOT NULL,\n  title TEXT NOT NULL,\n  kind TEXT NOT NULL DEFAULT 'follow_up'\n    CHECK (kind IN ('call', 'message', 'meeting', 'proposal', 'follow_up', 'other')),\n  status TEXT NOT NULL DEFAULT 'open'\n    CHECK (status IN ('open', 'completed', 'cancelled')),\n  priority TEXT NOT NULL DEFAULT 'normal'\n    CHECK (priority IN ('low', 'normal', 'high', 'urgent')),\n  due_at TEXT,\n  completed_at TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now')),\n  FOREIGN KEY (lead_id) REFERENCES leads(id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_crm_tasks_status_due\n  ON crm_tasks(status, due_at, priority);\nCREATE INDEX IF NOT EXISTS idx_crm_tasks_lead_status\n  ON crm_tasks(lead_id, status, due_at);\n\nCREATE TABLE IF NOT EXISTS crm_tags (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  slug TEXT NOT NULL UNIQUE,\n  color TEXT NOT NULL DEFAULT '#8b5cf6',\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS crm_lead_tags (\n  lead_id INTEGER NOT NULL,\n  tag_id INTEGER NOT NULL,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  PRIMARY KEY (lead_id, tag_id),\n  FOREIGN KEY (lead_id) REFERENCES leads(id) ON DELETE CASCADE,\n  FOREIGN KEY (tag_id) REFERENCES crm_tags(id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_crm_lead_tags_tag_lead\n  ON crm_lead_tags(tag_id, lead_id);",
  '0015_lead_consent_receipts.sql': "-- Durable consent receipt used by delayed CRM -> Meta lead-quality events.\n-- `consent_timestamp` is the client consent decision time in Unix milliseconds;\n-- `consent_recorded_at` is the independent server-side D1 write time.\n-- Existing rows are intentionally not backfilled: a receipt must not be invented.\n\nALTER TABLE leads ADD COLUMN consent_version INTEGER;\nALTER TABLE leads ADD COLUMN consent_source TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN consent_region TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN consent_timestamp INTEGER;\nALTER TABLE leads ADD COLUMN consent_recorded_at TEXT;\n\nCREATE INDEX IF NOT EXISTS idx_leads_consent_eligibility\n  ON leads(marketing_consent, consent_timestamp);",
  '0016_meta_diagnostics_retention.sql': "-- Keep Meta CAPI diagnostics useful without allowing the D1 table to grow\n-- forever. KV records already expire after 30 days; D1 keeps a longer\n-- 90-day operational window for the admin dashboard and incident review.\n\nDELETE FROM meta_capi_diagnostics\nWHERE created_at < datetime('now', '-90 days');\n\n-- Cloudflare Pages has no built-in migration runner or database cron. Run the\n-- lightweight cleanup once per 100 inserted diagnostics rows instead of on\n-- every event. The created_at index from migration 0002 makes the delete cheap.\nCREATE TRIGGER IF NOT EXISTS trg_meta_capi_diagnostics_retention\nAFTER INSERT ON meta_capi_diagnostics\nWHEN (NEW.id % 100) = 0\nBEGIN\n  DELETE FROM meta_capi_diagnostics\n  WHERE created_at < datetime('now', '-90 days');\nEND;",
  '0017_crm_correctness.sql': "-- Concurrency and idempotency guards for CRM mutations and Meta lead-quality state.\n-- Apply once after 0014_crm_workspace.sql and 0015_lead_consent_receipts.sql.\n\nALTER TABLE leads ADD COLUMN crm_action_id TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN quality_revision INTEGER NOT NULL DEFAULT 0\n  CHECK (quality_revision >= 0);\nALTER TABLE leads ADD COLUMN quality_updated_at TEXT;\nALTER TABLE leads ADD COLUMN quality_action_id TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN quality_processing INTEGER NOT NULL DEFAULT 0\n  CHECK (quality_processing IN (0, 1));\n\nUPDATE leads\nSET quality_updated_at = COALESCE(quality_updated_at, updated_at, created_at)\nWHERE COALESCE(quality, '') != '';\n\nCREATE INDEX IF NOT EXISTS idx_leads_quality_revision\n  ON leads(id, quality_revision);\n\nALTER TABLE crm_notes ADD COLUMN revision INTEGER NOT NULL DEFAULT 0\n  CHECK (revision >= 0);\nALTER TABLE crm_notes ADD COLUMN action_id TEXT NOT NULL DEFAULT '';\n\nALTER TABLE crm_tasks ADD COLUMN revision INTEGER NOT NULL DEFAULT 0\n  CHECK (revision >= 0);\nALTER TABLE crm_tasks ADD COLUMN action_id TEXT NOT NULL DEFAULT '';\n\n-- Empty action ids belong to rows created before this migration. New writes use\n-- a stable client action id so a retried request cannot create a duplicate.\nCREATE UNIQUE INDEX IF NOT EXISTS idx_crm_notes_action_id\n  ON crm_notes(action_id) WHERE action_id != '';\nCREATE UNIQUE INDEX IF NOT EXISTS idx_crm_tasks_action_id\n  ON crm_tasks(action_id) WHERE action_id != '';\n\nCREATE INDEX IF NOT EXISTS idx_crm_notes_lead_revision\n  ON crm_notes(lead_id, id, revision);\nCREATE INDEX IF NOT EXISTS idx_crm_tasks_lead_revision\n  ON crm_tasks(lead_id, id, revision);",
  '0018_tracking_request_nonces.sql': "-- Atomic replay protection and aggregate visibility for signed tracking\n-- requests. Apply after 0017_crm_correctness.sql.\n\nCREATE TABLE IF NOT EXISTS tracking_request_nonces (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  nonce_hash TEXT NOT NULL UNIQUE,\n  expires_at INTEGER NOT NULL,\n  created_at INTEGER NOT NULL DEFAULT (strftime('%s','now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_tracking_request_nonces_expires\n  ON tracking_request_nonces(expires_at);\n\n-- The browser is intentionally kept in monitor mode until requests can be\n-- signed by a trusted server-side component. This daily aggregate makes that\n-- state visible without retaining request bodies, identifiers, or raw nonces.\nCREATE TABLE IF NOT EXISTS tracking_signature_daily (\n  day TEXT NOT NULL,\n  endpoint TEXT NOT NULL,\n  mode TEXT NOT NULL CHECK (mode IN ('off', 'monitor', 'enforce')),\n  result TEXT NOT NULL CHECK (result IN ('valid', 'invalid', 'disabled')),\n  reason TEXT NOT NULL DEFAULT '',\n  count INTEGER NOT NULL DEFAULT 0,\n  updated_at INTEGER NOT NULL DEFAULT (strftime('%s','now')),\n  PRIMARY KEY (day, endpoint, mode, result, reason)\n);\n\nCREATE INDEX IF NOT EXISTS idx_tracking_signature_daily_day\n  ON tracking_signature_daily(day DESC);\n\n-- Keep nonce rows only for their short replay window. The modulo trigger\n-- amortises cleanup cost and never stores the raw client nonce.\nCREATE TRIGGER IF NOT EXISTS trg_tracking_request_nonces_retention\nAFTER INSERT ON tracking_request_nonces\nWHEN (NEW.id % 100) = 0\nBEGIN\n  DELETE FROM tracking_request_nonces\n  WHERE expires_at < strftime('%s','now');\nEND;\n\n-- Signature monitoring is operational telemetry, not long-term analytics.\nCREATE TRIGGER IF NOT EXISTS trg_tracking_signature_daily_retention\nAFTER INSERT ON tracking_signature_daily\nWHEN (NEW.rowid % 50) = 0\nBEGIN\n  DELETE FROM tracking_signature_daily\n  WHERE day < date('now', '-90 days');\nEND;\n\nCREATE TRIGGER IF NOT EXISTS trg_tracking_signature_daily_retention_update\nAFTER UPDATE OF count ON tracking_signature_daily\nWHEN (NEW.count % 500) = 0\nBEGIN\n  DELETE FROM tracking_signature_daily\n  WHERE day < date('now', '-90 days');\nEND;",
  '0019_lead_ingestion_idempotency.sql': "-- Durable idempotency ledger for lead submissions.\n-- A lead row keeps only the latest event_id after contact deduplication, so a\n-- separate history is required to recognize retries of every prior submission.\n\nCREATE TABLE IF NOT EXISTS lead_ingestions (\n  event_id TEXT PRIMARY KEY,\n  claim_token TEXT NOT NULL UNIQUE,\n  lead_id INTEGER,\n  submission_kind TEXT NOT NULL DEFAULT ''\n    CHECK (submission_kind IN ('', 'new', 'repeat', 'legacy')),\n  received_at TEXT NOT NULL DEFAULT (datetime('now')),\n  FOREIGN KEY (lead_id) REFERENCES leads(id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_lead_ingestions_lead_received\n  ON lead_ingestions(lead_id, received_at DESC);\n\n-- Preserve idempotency for the latest submission already stored on each lead.\nINSERT OR IGNORE INTO lead_ingestions (\n  event_id,\n  claim_token,\n  lead_id,\n  submission_kind,\n  received_at\n)\nSELECT\n  event_id,\n  'legacy:' || event_id,\n  id,\n  'legacy',\n  COALESCE(last_submitted_at, created_at, datetime('now'))\nFROM leads\nWHERE event_id IS NOT NULL AND event_id != '';",
  '0020_leads_soft_delete.sql': "-- Recoverable lead removal (\"корзина\") for spam, duplicates and junk submissions.\n-- A removed lead keeps its row and every related record, so a restore is lossless;\n-- only an explicit purge deletes data for good.\n-- `deleted_at` is the server-side D1 removal time; NULL means the lead is active.\n-- Existing rows are intentionally left active.\n\nALTER TABLE leads ADD COLUMN deleted_at TEXT;\nALTER TABLE leads ADD COLUMN deleted_reason TEXT NOT NULL DEFAULT '';\n\n-- Every list, counter and deduplication scan filters on `deleted_at IS NULL`,\n-- so this partial index keeps the active-lead path from scanning removed rows.\nCREATE INDEX IF NOT EXISTS idx_leads_active_recent\n  ON leads(id DESC) WHERE deleted_at IS NULL;\n\nCREATE INDEX IF NOT EXISTS idx_leads_deleted_at\n  ON leads(deleted_at DESC) WHERE deleted_at IS NOT NULL;",
  '0021_planner.sql': "-- Недельный планер админки.\n-- Одна строка = одна неделя (понедельник в ISO-формате), состояние целиком в JSON:\n-- цели недели, задачи и заметки по дням, трекер привычек и дневник.\nCREATE TABLE IF NOT EXISTS planner_weeks (\n  week_start TEXT PRIMARY KEY,\n  data_json TEXT NOT NULL DEFAULT '{}',\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_planner_weeks_updated\n  ON planner_weeks(updated_at DESC);",
  '0022_leads_form_source.sql': "-- Какая именно форма и какой её вариант принесли заявку.\n-- Сайт отправляет эти признаки в /api/lead с самого начала (ContactForm →\n-- home_contact_form, LandingForm → service_landing_form), но в leads их\n-- негде было хранить, поэтому разрезы «Форма» и «Вариант формы» в разделе\n-- «Воронка» были отключены. Это внутренние идентификаторы форм, не персональные\n-- данные и не рекламные метки, поэтому они сохраняются независимо от согласия.\n-- ВНИМАНИЕ: повторный запуск даст ошибку \"duplicate column name\" — это нормально.\nALTER TABLE leads ADD COLUMN form_id TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN form_variant TEXT NOT NULL DEFAULT '';\n\nCREATE INDEX IF NOT EXISTS idx_leads_form_created\n  ON leads(form_id, created_at);",
  '0023_ad_spend.sql': "-- Рекламные расходы, которые владелец вводит вручную (или загружает CSV).\n-- Без них воронка не может честно посчитать цену лида и окупаемость, а\n-- выдумывать эти числа нельзя. Одна строка = расход за день по источнику\n-- (и, если нужно, по конкретной кампании).\n--\n-- `source` совпадает с utm_source заявки (google, facebook, instagram…),\n-- `campaign` — с utm_campaign; пустая строка означает «весь источник целиком».\nCREATE TABLE IF NOT EXISTS ad_spend (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  day TEXT NOT NULL,                                  -- YYYY-MM-DD (UTC)\n  source TEXT NOT NULL DEFAULT '',\n  campaign TEXT NOT NULL DEFAULT '',\n  amount REAL NOT NULL DEFAULT 0\n    CHECK (amount >= 0 AND amount <= 1000000000),\n  currency TEXT NOT NULL DEFAULT 'USD'\n    CHECK (length(currency) = 3 AND currency = upper(currency) AND currency NOT GLOB '*[^A-Z]*'),\n  note TEXT NOT NULL DEFAULT '',\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- Повторный ввод того же дня и источника обновляет сумму, а не плодит строки.\nCREATE UNIQUE INDEX IF NOT EXISTS idx_ad_spend_slot\n  ON ad_spend(day, source, campaign, currency);\n\nCREATE INDEX IF NOT EXISTS idx_ad_spend_day\n  ON ad_spend(day DESC);",
  '0024_admin_goals.sql': "-- Цели на месяц: план по заявкам, целевым заявкам, выручке и потолку расхода.\n-- Без них админка отвечает только на вопрос «сколько было», но не на вопрос\n-- «успеваю ли». Одна строка — один месяц.\nCREATE TABLE IF NOT EXISTS admin_goals (\n  period TEXT PRIMARY KEY,                         -- YYYY-MM\n  leads_target INTEGER NOT NULL DEFAULT 0\n    CHECK (leads_target >= 0 AND leads_target <= 1000000),\n  qualified_target INTEGER NOT NULL DEFAULT 0\n    CHECK (qualified_target >= 0 AND qualified_target <= 1000000),\n  revenue_target REAL NOT NULL DEFAULT 0\n    CHECK (revenue_target >= 0 AND revenue_target <= 1000000000),\n  spend_cap REAL NOT NULL DEFAULT 0\n    CHECK (spend_cap >= 0 AND spend_cap <= 1000000000),\n  currency TEXT NOT NULL DEFAULT 'USD'\n    CHECK (length(currency) = 3 AND currency = upper(currency) AND currency NOT GLOB '*[^A-Z]*'),\n  note TEXT NOT NULL DEFAULT '',\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_admin_goals_period\n  ON admin_goals(period DESC);",
  '0025_crm_speed.sql': "-- Скорость работы с заявкой: время первого ответа и шаблоны сообщений.\n--\n-- `first_response_at` фиксируется один раз — при первом реальном касании\n-- (заметка, задача, смена этапа с «Новая»). Существующий `last_contacted_at`\n-- для этого не годится: он перезаписывается при каждом касании, поэтому по\n-- нему нельзя посчитать, за сколько ответили в первый раз. А именно это\n-- сильнее всего влияет на конверсию заявки в сделку.\n-- ВНИМАНИЕ: повторный запуск даст ошибку \"duplicate column name\" — это нормально.\nALTER TABLE leads ADD COLUMN first_response_at TEXT;\n\nCREATE INDEX IF NOT EXISTS idx_leads_first_response\n  ON leads(first_response_at);\n\n-- Готовые ответы: приветствие, запрос брифа, отправка КП, напоминание.\n-- В тексте можно использовать подстановки {имя}, {услуга}, {бюджет}.\nCREATE TABLE IF NOT EXISTS crm_templates (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  title TEXT NOT NULL,\n  body TEXT NOT NULL,\n  sort_order INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_crm_templates_sort\n  ON crm_templates(sort_order, id);",
  '0026_leads_geo_device.sql': "-- Страна и тип устройства заявки.\n--\n-- «Мобильный трафик конвертит хуже?» — один из самых частых вопросов при\n-- разборе кампаний, но ответить на него было нечем. Страна берётся из\n-- заголовка Cloudflare CF-IPCountry (двухбуквенный код, без города и без\n-- IP), тип устройства — грубо из user-agent: телефон, планшет или компьютер.\n-- Ни IP, ни полная строка user-agent не сохраняются.\n-- ВНИМАНИЕ: повторный запуск даст ошибку \"duplicate column name\" — это нормально.\nALTER TABLE leads ADD COLUMN country TEXT NOT NULL DEFAULT '';\nALTER TABLE leads ADD COLUMN device TEXT NOT NULL DEFAULT '';\n\nCREATE INDEX IF NOT EXISTS idx_leads_country_created\n  ON leads(country, created_at);\nCREATE INDEX IF NOT EXISTS idx_leads_device_created\n  ON leads(device, created_at);",
  '0027_web_vitals.sql': "-- Реальные Core Web Vitals посетителей (field data).\n--\n-- В проекте была измеряемая только лабораторная скорость через PageSpeed, а\n-- Google ранжирует по данным реальных пользователей. Метрики складываются\n-- сразу в суточные агрегаты: ни отдельных визитов, ни идентификаторов,\n-- ни IP тут не хранится — только счётчики по дню, метрике, типу устройства\n-- и странице.\nCREATE TABLE IF NOT EXISTS web_vitals_daily (\n  day TEXT NOT NULL,                 -- YYYY-MM-DD (UTC)\n  metric TEXT NOT NULL,              -- LCP | CLS | INP | TTFB\n  device TEXT NOT NULL DEFAULT '',   -- mobile | tablet | desktop\n  page_path TEXT NOT NULL DEFAULT '',\n  samples INTEGER NOT NULL DEFAULT 0,\n  value_sum REAL NOT NULL DEFAULT 0,\n  good INTEGER NOT NULL DEFAULT 0,\n  needs_improvement INTEGER NOT NULL DEFAULT 0,\n  poor INTEGER NOT NULL DEFAULT 0,\n  updated_at TEXT NOT NULL DEFAULT (datetime('now')),\n  PRIMARY KEY (day, metric, device, page_path)\n);\n\nCREATE INDEX IF NOT EXISTS idx_web_vitals_day\n  ON web_vitals_daily(day DESC, metric);",
  '0028_admin_alerts.sql': "-- Центр уведомлений: то, что требует вмешательства, но замечается поздно.\n--\n-- Заявка без ответа второй час, просроченный шаг, ошибки доставки в Meta,\n-- расход выше потолка — всё это видно, только если самому открыть админку.\n-- Здесь события собираются в одну таблицу и один раз уходят в Telegram.\n--\n-- `fingerprint` не даёт одному и тому же поводу дублироваться: правило\n-- строит стабильный ключ (например, «lead-no-answer:42»), и повторная\n-- проверка обновляет запись, а не плодит новые.\nCREATE TABLE IF NOT EXISTS admin_alerts (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  fingerprint TEXT NOT NULL UNIQUE,\n  kind TEXT NOT NULL,\n  severity TEXT NOT NULL DEFAULT 'attention'\n    CHECK (severity IN ('critical', 'attention', 'info')),\n  title TEXT NOT NULL,\n  detail TEXT NOT NULL DEFAULT '',\n  destination TEXT NOT NULL DEFAULT '',\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now')),\n  notified_at TEXT,\n  resolved_at TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_admin_alerts_open\n  ON admin_alerts(resolved_at, severity, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_admin_alerts_notify\n  ON admin_alerts(notified_at, resolved_at);",
  '0029_planner_template.sql': "-- Шаблон недели: повторяющиеся ритуалы, которые каждую неделю одни и те же\n-- («понедельник — разбор кампаний», «пятница — отчёт клиенту»).\n--\n-- Строка ровно одна: CHECK (id = 1) физически не даёт создать второй шаблон,\n-- а INSERT OR REPLACE по этому же id всегда переписывает существующий.\n-- Привычки сюда не входят — они и так переносятся с прошлой недели.\nCREATE TABLE IF NOT EXISTS planner_template (\n  id INTEGER PRIMARY KEY CHECK (id = 1),\n  data_json TEXT NOT NULL DEFAULT '{}',\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);",
  '0030_pagespeed_history.sql': "-- История замеров PageSpeed: раньше результаты жили только в localStorage\n-- браузера и протухали через 12 часов, поэтому «стало быстрее или медленнее»\n-- было не с чем сравнить.\n--\n-- Одна строка = один день на страницу и режим: перезапуск в тот же день\n-- переписывает запись, а не плодит точки. Для тренда суточной точности хватает.\nCREATE TABLE IF NOT EXISTS pagespeed_history (\n  day TEXT NOT NULL,                 -- YYYY-MM-DD (UTC)\n  url TEXT NOT NULL,\n  strategy TEXT NOT NULL,            -- mobile | desktop\n  performance INTEGER,\n  accessibility INTEGER,\n  best_practices INTEGER,\n  seo INTEGER,\n  lcp_ms REAL,\n  cls REAL,\n  tbt_ms REAL,\n  total_bytes INTEGER,\n  checked_at TEXT NOT NULL,\n  PRIMARY KEY (day, url, strategy)\n);\n\nCREATE INDEX IF NOT EXISTS idx_pagespeed_history_day\n  ON pagespeed_history(day DESC, strategy);",
  '0031_media_alt.sql': "-- Alt-тексты картинок медиатеки.\n--\n-- Хранить их в метаданных R2 нельзя без перезаливки файла: объектное\n-- хранилище не умеет менять customMetadata на месте, пришлось бы копировать\n-- объект и менять публичную ссылку. Поэтому подпись живёт отдельной строкой,\n-- а ключ объекта связывает её с файлом.\nCREATE TABLE IF NOT EXISTS media_alt (\n  object_key TEXT PRIMARY KEY,\n  alt TEXT NOT NULL DEFAULT '',\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);",
  '0032_clients.sql': "-- Клиенты: то, что начинается после выигранной сделки.\n--\n-- CRM доводит человека до «Выиграно» и на этом заканчивается, а работа с\n-- абонентом только начинается: договор, отчёты каждый месяц, доступы,\n-- продление. Раньше всё это жило в голове и переписке.\n--\n-- `lead_id` связывает клиента с заявкой, из которой он вырос, но может быть\n-- пустым: клиента можно завести и руками, если он пришёл не через сайт.\n-- Частичный уникальный индекс не даёт сделать двух клиентов из одной сделки.\nCREATE TABLE IF NOT EXISTS clients (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  lead_id INTEGER,\n  name TEXT NOT NULL,\n  company TEXT NOT NULL DEFAULT '',\n  status TEXT NOT NULL DEFAULT 'active'\n    CHECK (status IN ('active', 'paused', 'finished')),\n  started_at TEXT NOT NULL DEFAULT (date('now')),\n  paused_until TEXT,\n  finished_at TEXT,\n  finish_reason TEXT NOT NULL DEFAULT '',\n  contact_method TEXT NOT NULL DEFAULT '',\n  contact_value TEXT NOT NULL DEFAULT '',\n  -- Смещение часового пояса клиента в минутах от UTC: чтобы админка могла\n  -- показать «сейчас у клиента 07:14» и удержать от звонка не вовремя.\n  timezone_offset INTEGER,\n  -- Услуги списком: [{\"name\":\"Meta Ads\",\"status\":\"active\",\"since\":\"2026-08\"}]\n  services TEXT NOT NULL DEFAULT '[]',\n  retainer_amount REAL NOT NULL DEFAULT 0\n    CHECK (retainer_amount >= 0 AND retainer_amount <= 1000000000),\n  retainer_currency TEXT NOT NULL DEFAULT 'USD'\n    CHECK (length(retainer_currency) = 3 AND retainer_currency = upper(retainer_currency)),\n  billing_day INTEGER CHECK (billing_day IS NULL OR (billing_day >= 1 AND billing_day <= 28)),\n  contract_number TEXT NOT NULL DEFAULT '',\n  contract_signed_at TEXT,\n  contract_ends_at TEXT,\n  contract_auto_renew INTEGER NOT NULL DEFAULT 0,\n  contract_file_url TEXT NOT NULL DEFAULT '',\n  scope_included TEXT NOT NULL DEFAULT '',\n  scope_excluded TEXT NOT NULL DEFAULT '',\n  next_touch_at TEXT,\n  next_touch_text TEXT NOT NULL DEFAULT '',\n  media_folder TEXT NOT NULL DEFAULT '',\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_clients_status ON clients(status, name);\nCREATE UNIQUE INDEX IF NOT EXISTS idx_clients_lead ON clients(lead_id) WHERE lead_id IS NOT NULL;\n\n-- Месяц работы с клиентом одной строкой: и отметка об отправленном отчёте,\n-- и его результаты. Это одна и та же сущность — «как прошёл август», —\n-- и разносить её по двум таблицам значило бы дважды искать один месяц.\nCREATE TABLE IF NOT EXISTS client_months (\n  client_id INTEGER NOT NULL,\n  month TEXT NOT NULL,                       -- YYYY-MM\n  report_sent_at TEXT,\n  report_url TEXT NOT NULL DEFAULT '',\n  spend REAL,\n  spend_currency TEXT NOT NULL DEFAULT '',\n  leads INTEGER,\n  sales INTEGER,\n  revenue REAL,\n  note TEXT NOT NULL DEFAULT '',\n  updated_at TEXT NOT NULL DEFAULT (datetime('now')),\n  PRIMARY KEY (client_id, month)\n);\n\nCREATE INDEX IF NOT EXISTS idx_client_months_month ON client_months(month DESC, client_id);\n\n-- Доступы: только факт наличия, без паролей. Пароли обязаны жить в менеджере\n-- паролей, а не в вебе под одним общим паролем администратора.\nCREATE TABLE IF NOT EXISTS client_access (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  client_id INTEGER NOT NULL,\n  name TEXT NOT NULL,\n  status TEXT NOT NULL DEFAULT 'waiting'\n    CHECK (status IN ('waiting', 'granted', 'revoked')),\n  note TEXT NOT NULL DEFAULT '',\n  changed_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_client_access_client ON client_access(client_id, name);\n\n-- Памятки по клиенту: кто принимает решения, что не любит, как думает.\nCREATE TABLE IF NOT EXISTS client_notes (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  client_id INTEGER NOT NULL,\n  body TEXT NOT NULL,\n  pinned INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_client_notes_client\n  ON client_notes(client_id, pinned DESC, created_at DESC);",
  '0033_finance.sql': "-- Финансы: счета, расходы, время и настройки в одном разделе.\n--\n-- Три темы связаны одной логикой — деньги клиента от выставленного счёта до\n-- прибыли в кармане и цена этих денег в часах жизни.\n--\n-- «Просрочен» нигде не хранится: это `status = 'issued'` и `due_at` в\n-- прошлом. Хранимый статус пришлось бы пересчитывать по таймеру, и он\n-- обязательно разъехался бы с реальностью.\nCREATE TABLE IF NOT EXISTS invoices (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  client_id INTEGER,\n  number TEXT NOT NULL DEFAULT '',\n  period TEXT NOT NULL DEFAULT '',                    -- YYYY-MM, за какой месяц\n  amount REAL NOT NULL DEFAULT 0\n    CHECK (amount >= 0 AND amount <= 1000000000),\n  currency TEXT NOT NULL DEFAULT 'USD'\n    CHECK (length(currency) = 3 AND currency = upper(currency)),\n  issued_at TEXT,\n  due_at TEXT,\n  paid_at TEXT,\n  status TEXT NOT NULL DEFAULT 'draft'\n    CHECK (status IN ('draft', 'issued', 'paid', 'cancelled')),\n  note TEXT NOT NULL DEFAULT '',\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_invoices_status ON invoices(status, due_at);\nCREATE INDEX IF NOT EXISTS idx_invoices_client ON invoices(client_id, period DESC);\n\n-- Свои расходы: сервисы, подписки, реклама на себя. Ровно то, что вычитается\n-- из дохода, чтобы прибыль была прибылью, а не выручкой.\nCREATE TABLE IF NOT EXISTS finance_expenses (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  day TEXT NOT NULL,\n  category TEXT NOT NULL DEFAULT '',\n  amount REAL NOT NULL DEFAULT 0\n    CHECK (amount >= 0 AND amount <= 1000000000),\n  currency TEXT NOT NULL DEFAULT 'USD'\n    CHECK (length(currency) = 3 AND currency = upper(currency)),\n  note TEXT NOT NULL DEFAULT '',\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_finance_expenses_day ON finance_expenses(day DESC);\n\n-- Часы по клиентам: единственный способ узнать реальную ставку в час и\n-- увидеть, кто платит мало за много вашего времени.\nCREATE TABLE IF NOT EXISTS time_entries (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  client_id INTEGER,\n  day TEXT NOT NULL,\n  hours REAL NOT NULL DEFAULT 0\n    CHECK (hours > 0 AND hours <= 24),\n  note TEXT NOT NULL DEFAULT '',\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_time_entries_day ON time_entries(day DESC, client_id);\n\n-- Настройки раздела одной строкой. Ставка налога не угадывается: у режимов\n-- она разная, а ошибка в проценте — это ошибка в отложенных деньгах.\n-- `requisites` пока не используется: поле заложено, чтобы позже добавить\n-- выгрузку счёта документом без новой миграции.\nCREATE TABLE IF NOT EXISTS finance_settings (\n  id INTEGER PRIMARY KEY CHECK (id = 1),\n  tax_rate REAL NOT NULL DEFAULT 0\n    CHECK (tax_rate >= 0 AND tax_rate <= 100),\n  target_hourly_rate REAL NOT NULL DEFAULT 0\n    CHECK (target_hourly_rate >= 0),\n  main_currency TEXT NOT NULL DEFAULT 'USD',\n  requisites TEXT NOT NULL DEFAULT '',\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);",
  '0034_page_locks.sql': "-- Доступ к страницам: закрытая страница отдаёт заглушку вместо содержимого,\n-- но остаётся на месте — её по-прежнему можно редактировать и смотреть в\n-- предпросмотре редактора.\n--\n-- Строк здесь ровно столько, сколько у сайта страниц (десятки, не тысячи):\n-- проверка «закрыта ли страница» выполняется на каждом запросе к сайту и\n-- читает эту таблицу через кэш, поэтому таблица обязана оставаться крошечной.\nCREATE TABLE IF NOT EXISTS page_locks (\n  path TEXT PRIMARY KEY,\n  locked INTEGER NOT NULL DEFAULT 0\n    CHECK (locked IN (0, 1)),\n  -- Закрывать вместе с вложенными адресами: /blog закрывает и /blog/<статья>.\n  include_children INTEGER NOT NULL DEFAULT 0\n    CHECK (include_children IN (0, 1)),\n  preset TEXT NOT NULL DEFAULT 'development'\n    CHECK (preset IN ('development', 'update', 'soon', 'custom')),\n  title TEXT NOT NULL DEFAULT '',\n  message TEXT NOT NULL DEFAULT '',\n  eta TEXT,                                           -- YYYY-MM-DD, необязательно\n  hide_in_nav INTEGER NOT NULL DEFAULT 1\n    CHECK (hide_in_nav IN (0, 1)),\n  show_subscribe INTEGER NOT NULL DEFAULT 1\n    CHECK (show_subscribe IN (0, 1)),\n  cta_path TEXT NOT NULL DEFAULT '/',                 -- вторая кнопка заглушки\n  locked_at TEXT,\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_page_locks_locked ON page_locks(locked, path);\n\n-- Журнал изменений: когда и какая страница закрывалась и открывалась.\n-- Сырые IP и user-agent не хранятся — только хеш, как в остальной статистике.\n-- Нужен ровно для одного: изменение доступа не должно быть незаметным.\nCREATE TABLE IF NOT EXISTS page_lock_events (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  path TEXT NOT NULL,\n  action TEXT NOT NULL\n    CHECK (action IN ('lock', 'unlock', 'update', 'preview')),\n  actor_hash TEXT NOT NULL DEFAULT '',\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_page_lock_events_created ON page_lock_events(created_at DESC);\n\n-- Кто оставил почту на заглушке «сообщить, когда откроется».\n--\n-- Намеренно отдельно от `leads`: это не заявка. Попади такая запись в общую\n-- таблицу — она посчиталась бы в воронке, цене лида и ROMI, а показывать\n-- выдуманные цифры в этом проекте нельзя.\nCREATE TABLE IF NOT EXISTS page_lock_subscribers (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  path TEXT NOT NULL,\n  email TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  notified_at TEXT\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_page_lock_subscribers_unique\n  ON page_lock_subscribers(path, email);\nCREATE INDEX IF NOT EXISTS idx_page_lock_subscribers_created\n  ON page_lock_subscribers(created_at DESC);",
  '0035_page_lock_contacts.sql': "-- Телефон и телеграм на заглушке рядом с почтой + отдельное согласие на\n-- маркетинг, по которому уходит событие в Meta.\n--\n-- Отдельной миграцией, а не правкой 0034: та могла быть уже применена, и\n-- новые колонки в ней молча не появились бы.\nALTER TABLE page_lock_subscribers ADD COLUMN phone TEXT NOT NULL DEFAULT '';\n\nALTER TABLE page_lock_subscribers ADD COLUMN telegram TEXT NOT NULL DEFAULT '';\n\n-- Согласие на маркетинг — отдельная галочка, по умолчанию снятая. Без неё\n-- в Meta не уходит ничего: серверные события в этом проекте отправляются\n-- только при явном согласии, и это правило не ослабляется.\nALTER TABLE page_lock_subscribers ADD COLUMN marketing_consent INTEGER NOT NULL DEFAULT 0;\n\n-- Квитанция согласия: когда и из какой страны его дали. Нужна, чтобы согласие\n-- можно было предъявить, а не утверждать на словах.\nALTER TABLE page_lock_subscribers ADD COLUMN consent_at TEXT;\n\nALTER TABLE page_lock_subscribers ADD COLUMN consent_region TEXT NOT NULL DEFAULT '';\n\n-- Повторов не должно быть ни по почте, ни по телефону, ни по телеграму, но\n-- человек оставляет что-то одно. Обычный уникальный индекс по паре считал бы\n-- все записи с пустым полем одним и тем же контактом, поэтому индексы\n-- частичные: каждый следит только за заполненным полем.\nDROP INDEX IF EXISTS idx_page_lock_subscribers_unique;\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_page_lock_subscribers_email\n  ON page_lock_subscribers(path, email) WHERE email <> '';\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_page_lock_subscribers_phone\n  ON page_lock_subscribers(path, phone) WHERE phone <> '';\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_page_lock_subscribers_telegram\n  ON page_lock_subscribers(path, telegram) WHERE telegram <> '';",
  '0036_admin_2fa.sql': "-- Двухфакторный вход в админку: пароль плюс одноразовый код из приложения\n-- (Google Authenticator и любое совместимое).\n--\n-- Почему это отдельная таблица, а не переменная окружения: секрет создаётся\n-- в самой админке при настройке, а переменную в Cloudflare Pages нельзя\n-- поменять без пересборки сайта.\n--\n-- Одна строка на весь сайт (`id = 1`): администратор здесь один, общий пароль\n-- никуда не делся. CHECK не даёт случайно завести вторую конфигурацию, из-за\n-- которой было бы неясно, какой секрет настоящий.\nCREATE TABLE IF NOT EXISTS admin_2fa (\n  id INTEGER PRIMARY KEY CHECK (id = 1),\n\n  -- Секрет TOTP в base32. Он же лежит в приложении на телефоне.\n  totp_secret TEXT NOT NULL,\n\n  -- Пока NULL, защита настроена, но не включена: секрет создан и показан, а\n  -- подтверждающий код ещё не введён. Так неудачная настройка не запирает\n  -- вход.\n  enabled_at INTEGER,\n\n  -- Хеши резервных кодов (SHA-256), JSON-массивом. Сами коды показываются\n  -- один раз при включении и в базе не хранятся: из хеша код не восстановить,\n  -- поэтому доступ к D1 не даёт входа.\n  backup_codes TEXT NOT NULL DEFAULT '[]',\n\n  -- Номер 30-секундного интервала, по которому уже входили. Не даёт\n  -- использовать один и тот же код дважды, пока он не истёк.\n  last_step INTEGER NOT NULL DEFAULT 0,\n\n  created_at INTEGER NOT NULL DEFAULT (strftime('%s','now')),\n  updated_at INTEGER NOT NULL DEFAULT (strftime('%s','now'))\n);",
  '0037_form_guard_daily.sql': "-- Счётчик отказов на форме заявки, по одной строке на день и причину.\n--\n-- Нужен ровно для одного вопроса: не отсекает ли защита живых людей. Без него\n-- «Turnstile иногда ошибается» остаётся ощущением, а не числом.\n--\n-- Суточный агрегат, а не запись на каждый отказ: на бесплатном тарифе\n-- Cloudflare лимит записей в D1 конечный, а поток ботов — это как раз тот\n-- случай, когда подробный журнал стоил бы дороже самой атаки.\nCREATE TABLE IF NOT EXISTS form_guard_daily (\n  day TEXT NOT NULL,\n\n  -- missing_token — виджет не отработал (повод проверить сайт),\n  -- invalid_token — Cloudflare отклонил (обычная работа защиты),\n  -- verification_unavailable — не удалось спросить Cloudflare.\n  reason TEXT NOT NULL,\n\n  count INTEGER NOT NULL DEFAULT 0,\n\n  -- Дневной бюджет записей исчерпан: значит, был всплеск и настоящее число\n  -- больше сохранённого. Интерфейс обязан показывать такой день как «не\n  -- меньше N», а не как точное значение.\n  throttled INTEGER NOT NULL DEFAULT 0,\n\n  updated_at INTEGER NOT NULL DEFAULT (strftime('%s','now')),\n\n  PRIMARY KEY (day, reason)\n);",
  '0038_meta_outbox_cleanup_index.sql': "-- Индекс под уборку очереди досылки событий Meta.\n--\n-- Зачем. Уборка ищет записи по паре «статус + когда обновлена»:\n--\n--   DELETE FROM meta_outbox WHERE status='sent' AND updated_at < ...\n--\n-- Существующие индексы — (status, next_retry_at) и (event_name, event_id) —\n-- по `updated_at` не помогают. Поэтому база отбирала все записи со статусом\n-- `sent` (а это почти вся таблица) и у каждой проверяла дату вручную.\n-- На бесплатном тарифе Cloudflare это съедало суточный лимит в 5 млн\n-- прочитанных строк.\n--\n-- С этим индексом уборка читает ровно те строки, которые удалит.\n\nCREATE INDEX IF NOT EXISTS idx_meta_outbox_status_updated\n  ON meta_outbox(status, updated_at);",
  '0039_leads_dedupe_index.sql': "-- Поиск дублей заявки по индексу вместо перебора последних 500.\n--\n-- Как было: приём заявки читал 500 свежих строк и сравнивал контакты в коде.\n-- Контакт старше этих пятисот не находился — человек, писавший год назад,\n-- создавал новую заявку вместо того, чтобы поднять существующую. Счётчик\n-- обращений начинался заново, история терялась, в CRM появлялся дубль.\n--\n-- Почему нельзя было искать прямо по email и phone: они хранятся так, как их\n-- набрал человек. «+7 999 123-45-67» и «8 (999) 123-45-67» — один номер,\n-- «Ivan@Mail.ru» и «ivan@mail.ru» — одна почта. Сравнение шло по приведённым\n-- значениям, а приведение жило в коде, и SQL о нём не знал.\n--\n-- Теперь приведённые ключи хранятся рядом и покрыты индексами. Правило\n-- приведения — то же, что в коде (`contactKeys` в functions/_lib/leads.ts):\n--   почта    — без пробелов по краям, строчными;\n--   телефон  — только цифры, последние десять;\n--   телеграм — без ведущей собаки, строчными.\n--\n-- Пусто хранится как NULL, а не пустая строка. Это принципиально: иначе все\n-- заявки без телефона имели бы одинаковый ключ '' и склеились бы в одну.\n\nALTER TABLE leads ADD COLUMN dedupe_email TEXT;\nALTER TABLE leads ADD COLUMN dedupe_phone TEXT;\nALTER TABLE leads ADD COLUMN dedupe_telegram TEXT;\n\n-- Индексы частичные: строки без ключа в них не попадают и места не занимают.\nCREATE INDEX IF NOT EXISTS idx_leads_dedupe_email\n  ON leads (dedupe_email) WHERE dedupe_email IS NOT NULL;\nCREATE INDEX IF NOT EXISTS idx_leads_dedupe_phone\n  ON leads (dedupe_phone) WHERE dedupe_phone IS NOT NULL;\nCREATE INDEX IF NOT EXISTS idx_leads_dedupe_telegram\n  ON leads (dedupe_telegram) WHERE dedupe_telegram IS NOT NULL;\n\n-- Заполнение уже существующих заявок.\n--\n-- У SQLite нет регулярных выражений, поэтому цифры из телефона выбираются\n-- вложенными заменами. Перечислены те знаки, которыми люди на самом деле\n-- разделяют номер: плюс, пробел, дефис, скобки, точка и неразрывный пробел.\nUPDATE leads\nSET\n  dedupe_email = NULLIF(LOWER(TRIM(COALESCE(email, ''))), ''),\n\n  dedupe_telegram = NULLIF(\n    LOWER(TRIM(\n      CASE\n        WHEN SUBSTR(TRIM(COALESCE(telegram_username, '')), 1, 1) = '@'\n          THEN SUBSTR(TRIM(COALESCE(telegram_username, '')), 2)\n        ELSE TRIM(COALESCE(telegram_username, ''))\n      END\n    )),\n    ''\n  ),\n\n  dedupe_phone = (\n    SELECT\n      CASE\n        WHEN LENGTH(digits) >= 10 THEN SUBSTR(digits, LENGTH(digits) - 9, 10)\n        WHEN LENGTH(digits) > 0 THEN digits\n        ELSE NULL\n      END\n    FROM (\n      SELECT REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(\n        COALESCE(leads.phone, ''),\n        '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''), CHAR(160), '') AS digits\n    )\n  );",
  '0040_versions_retention.sql': "-- История версий перестаёт расти без конца: хранятся последние 50 на объект.\n--\n-- Каждое сохранение статьи и каждое сохранение блока текстов сайта добавляли\n-- строку, и ничто их не удаляло. У активно редактируемой страницы это сотни\n-- снимков целого документа — на бесплатном тарифе Cloudflare D1 размер базы\n-- ограничен, и первым делом он кончился бы именно здесь.\n--\n-- Пятьдесят версий покрывают любую реальную потребность откатиться: это\n-- несколько месяцев правок даже при ежедневной работе. Кто откатывается на\n-- пятьдесят первую версию назад, тот берёт текст не из истории, а из головы.\n--\n-- Почему триггер, а не уборка в коде: писать историю может не только админка\n-- (перенос контента с production, восстановление версии), и правило должно\n-- держаться в самой базе, а не в одном из путей записи.\n\n-- Индекс под условие удаления: без него триггер на каждой вставке читал бы всю\n-- историю объекта. Для статей нужный индекс уже есть (миграция 0006), здесь —\n-- только по идентификатору, чтобы отбор «пятидесятая сверху» шёл по нему.\nCREATE INDEX IF NOT EXISTS idx_article_versions_slug_id\n  ON article_versions(slug, id DESC);\nCREATE INDEX IF NOT EXISTS idx_site_section_versions_key_id\n  ON site_section_versions(section_key, id DESC);\n\n-- Отсчёт по id, а не по created_at: время в SQLite пишется с точностью до\n-- секунды, и несколько сохранений подряд получают одинаковую метку — порядок\n-- удаления стал бы неопределённым, и триггер мог бы срезать не ту версию.\nCREATE TRIGGER IF NOT EXISTS trg_article_versions_retention\nAFTER INSERT ON article_versions\nBEGIN\n  DELETE FROM article_versions\n  WHERE slug = NEW.slug\n    AND id <= (\n      SELECT id FROM article_versions\n      WHERE slug = NEW.slug\n      ORDER BY id DESC\n      LIMIT 1 OFFSET 50\n    );\nEND;\n\nCREATE TRIGGER IF NOT EXISTS trg_site_section_versions_retention\nAFTER INSERT ON site_section_versions\nBEGIN\n  DELETE FROM site_section_versions\n  WHERE section_key = NEW.section_key\n    AND id <= (\n      SELECT id FROM site_section_versions\n      WHERE section_key = NEW.section_key\n      ORDER BY id DESC\n      LIMIT 1 OFFSET 50\n    );\nEND;\n\n-- Разовая уборка того, что уже накопилось. Триггеры срабатывают только на\n-- новых вставках и старые строки сами не тронут.\nDELETE FROM article_versions\nWHERE id NOT IN (\n  SELECT id FROM (\n    SELECT id, ROW_NUMBER() OVER (PARTITION BY slug ORDER BY id DESC) AS position\n    FROM article_versions\n  )\n  WHERE position <= 50\n);\n\nDELETE FROM site_section_versions\nWHERE id NOT IN (\n  SELECT id FROM (\n    SELECT id, ROW_NUMBER() OVER (PARTITION BY section_key ORDER BY id DESC) AS position\n    FROM site_section_versions\n  )\n  WHERE position <= 50\n);",
};
